        }
        $totalWeightOption = $this->totalWeight;
        if ($totalWeightOption->isDefined()) {
            $totalWeight = $totalWeightOption->get();
            $dataArray['totalWeight'] = $totalWeight;
        }
        $shipmentSpecialServicesOption = $this->shipmentSpecialServices;
        if ($shipmentSpecialServicesOption->isDefined()) {
            $shipmentSpecialServices = $shipmentSpecialServicesOption->get();
            $dataArray['shipmentSpecialServices'] = $normalizationTarget->model($shipmentSpecialServices);
        }
        $customsClearanceDetailOption = $this->customsClearanceDetail;
        if ($customsClearanceDetailOption->isDefined()) {
            $customsClearanceDetail = $customsClearanceDetailOption->get();
            $dataArray['customsClearanceDetail'] = $normalizationTarget->model($customsClearanceDetail);
        }
        $smartPostInfoDetailOption = $this->smartPostInfoDetail;
        if ($smartPostInfoDetailOption->isDefined()) {
            $smartPostInfoDetail = $smartPostInfoDetailOption->get();
            $dataArray['smartPostInfoDetail'] = $normalizationTarget->model($smartPostInfoDetail);
        }
        $dataArray += $this->getAdditionalProperties();

        return $dataArray;
    }

    public function toBuilder(): RequestedShipmentBuilder
    {
        return new RequestedShipmentBuilder(
            $this->shipper,
            $this->recipient,
            $this->pickupType,
            $this->requestedPackageLineItems,
            $this->pickupDetail,
            $this->serviceType,
            $this->preferredCurrency,
            $this->rateRequestType,
            $this->shipDateStamp,
            $this->documentShipment,
            $this->variableHandlingChargeDetail,
            $this->packagingType,
            $this->totalPackageCount,
            $this->totalWeight,
            $this->shipmentSpecialServices,
            $this->customsClearanceDetail,
            $this->smartPostInfoDetail,
            $this->additionalProperties,
        );
    }
}
